using System.IO;
using FluentAssertions;
using IdeaInfinityIT.EnterpriseTestGen.Core.Models;
using IdeaInfinityIT.EnterpriseTestGen.Runner;
using Xunit;

namespace IdeaInfinityIT.EnterpriseTestGen.Tests
{
    public class RealCoverageAndRunnerTests
    {
        private readonly DotnetTestRunner _runner = new();

        [Fact]
        public void ParseCoberturaXml_ExtractsRealLineAndBranchCoverageAccurately()
        {
            // Arrange - standard Cobertura XML generated by Coverlet
            var xmlContent = @"<?xml version=""1.0"" encoding=""utf-8""?>
<coverage line-rate=""0.875"" branch-rate=""0.725"" version=""1.9"" timestamp=""1600000000"">
  <sources>
    <source>G:\App</source>
  </sources>
  <packages>
    <package name=""App.Services"" line-rate=""0.875"" branch-rate=""0.725"">
      <classes>
        <class name=""App.Services.OrderService"" line-rate=""0.875"" branch-rate=""0.725"" />
      </classes>
    </package>
  </packages>
</coverage>";

            var tempXml = Path.GetTempFileName();
            try
            {
                File.WriteAllText(tempXml, xmlContent);
                var summary = new TestRunSummary();

                // Act
                _runner.ParseCoberturaXml(tempXml, summary);

                // Assert (NO FABRICATION: must equal exactly line-rate * 100)
                summary.CoverageCollected.Should().BeTrue();
                summary.LineCoveragePercentage.Should().Be(87.5);
                summary.BranchCoveragePercentage.Should().Be(72.5);
                summary.CoverageReportPath.Should().Be(tempXml);
            }
            finally
            {
                if (File.Exists(tempXml)) File.Delete(tempXml);
            }
        }

        [Fact]
        public void ParseRealCoverage_WhenNoCoverageReportExists_ReportsZeroAndDoesNotFabricate()
        {
            // Arrange
            var emptyDir = Path.Combine(Path.GetTempPath(), "EmptyTestResults_" + Path.GetRandomFileName());
            Directory.CreateDirectory(emptyDir);

            try
            {
                var summary = new TestRunSummary { TotalTests = 10, Passed = 10 };

                // Act
                _runner.ParseRealCoverage(emptyDir, summary);

                // Assert: Must NOT use fabricated 70% + Passed * 2 formula
                summary.CoverageCollected.Should().BeFalse();
                summary.LineCoveragePercentage.Should().Be(0.0);
                summary.BranchCoveragePercentage.Should().Be(0.0);
                summary.Logs.Should().Contain(l => l.Contains("[Coverage]"));
            }
            finally
            {
                if (Directory.Exists(emptyDir)) Directory.Delete(emptyDir, true);
            }
        }
    }
}
